"""Close blocked-run evidence only after validation; never mutate production."""
from pathlib import Path
import json,hashlib,subprocess,importlib.util,re,datetime
R=Path.cwd();P=Path(__file__).resolve().parent
save=lambda n,x:(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
tests=json.loads((P/'TEST_RESULTS.json').read_text());assert tests['status']=='COMPLETE'
full=json.loads((P/'validation/full-results.json').read_text());oldPath=R/'docs/fundamental-data-engine/evidence/2026-10-20-production-authority-final-activation/validation/full-case-statuses.json';old=json.loads(oldPath.read_text())
current={};failures=[]
for suite in full['testResults']:
 name=str(Path(suite['name']).relative_to(R/'tests'))
 for case in suite['assertionResults']:
  key=name+'::'+case['fullName'];current[key]=case['status']
  if case['status']=='failed':failures.append({'case':key,'inHistoricalFailureSet':old.get(key)=='failed','messages':case.get('failureMessages',[])})
oldFailed={k for k,v in old.items() if v=='failed'};failed={k for k,v in current.items() if v=='failed'}
save('REGRESSION_RESULTS.json',{'currentHead':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'historicalComparison':{'path':str(oldPath.relative_to(R)),'sha256':sha(oldPath),'oldFailed':len(oldFailed),'sameFailureSet':oldFailed==failed,'additionalFailures':sorted(failed-oldFailed),'historicalFailuresNotFailedNow':sorted(oldFailed-failed)},'passed':full['numPassedTests'],'failed':full['numFailedTests'],'total':full['numTotalTests'],'failures':failures,'classificationNote':'This task changed no tracked implementation/test file or production state. Do not equate current starting-HEAD failures with the older historical failure set; exact deltas are listed. No test was changed, skipped or suppressed.'})
counts={'full':{'passed':full['numPassedTests'],'failed':full['numFailedTests'],'total':full['numTotalTests']}}
for name in ['scoring','focused','api']:
 text=(P/'validation'/f'{name}.log').read_text();text=re.sub(r'\x1b\[[0-9;]*m','',text)
 if name=='api':counts[name]={'passed':int(re.search(r'# pass (\d+)',text).group(1)),'failed':int(re.search(r'# fail (\d+)',text).group(1))}
 else:
  match=re.search(r'^\s*Tests\s+(.+)$',text,re.M);line=match.group(1) if match else ''
  passed=re.search(r'(\d+) passed',line);bad=re.search(r'(\d+) failed',line)
  counts[name]={'passed':int(passed.group(1)) if passed else 0,'failed':int(bad.group(1)) if bad else 0}
tests['summaries']=counts;tests['productionScoringReplay']={'status':'NOT_RUN','reason':'Phase1 market prerequisite blocked; no production scorecards or accepted immutable scoring dataset exist. Existing scoring/golden/readiness tests are not a production replay.'};save('TEST_RESULTS.json',tests)
spec=importlib.util.spec_from_file_location('inventory',R/'docs/fundamental-data-engine/evidence/2026-10-20-production-authority-final-activation/inspect-state.py');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
after=mod.inspect(R/'data/vn30.sqlite');before=json.loads((P/'DATABASE_BEFORE.json').read_text());save('DATABASE_AFTER.json',after)
changes=[]
for table in sorted(set(before['tables'])|set(after['tables'])):
 if before['tables'].get(table)!=after['tables'].get(table):changes.append(table)
assert not changes and before['sha256']==after['sha256'] and before['schemaObjects']==after['schemaObjects'],'UNEXPECTED_PRODUCTION_MUTATION'
audit={'status':'PASS_NO_PRODUCTION_MUTATION','beforeSHA256':before['sha256'],'afterSHA256':after['sha256'],'identicalDatabaseBytes':True,'logicalRowAndSchemaComparison':'PASS_ALL_TABLES','changedTables':changes,'beforeHead':before['dependencyHeads'],'afterHead':after['dependencyHeads'],'tableCounts':{t:{'before':before['tables'][t]['rows'],'after':after['tables'][t]['rows']} for t in ['data_initialization_acceptance','scoring_dataset_binding','analytical_artifact','production_dependency_publication','market_boundary_record','market_boundary_ranking_publication','market_boundary_decision_seal','ledger_transaction','dependency_release']},'investmentTransactionsCreated':0,'ordersSubmitted':0,'unauthorizedFallback':False,'futureEODCompletionDetectedAndRejected':True,'futureInformationAdmitted':False,'expectedFilesystemWrites':['fresh TCBS raw/manifest/capture directory','this evidence package','ignored build/test caches'],'trackedImplementationFilesChanged':subprocess.check_output(['git','diff','--name-only'],text=True).splitlines()};assert not audit['trackedImplementationFilesChanged'];save('PRODUCTION_MUTATION_AUDIT.json',audit)
q=json.loads((P/'MARKET_QUALIFICATION.json').read_text());refresh=json.loads((P/'MARKET_REFRESH_RESULT.json').read_text());pre=json.loads((P/'PREFLIGHT.json').read_text())
assert pre['fullUniverse']==30 and pre['eligible']==29
model=json.loads((R/'docs/fundamental-data-engine/evidence/2026-10-20-production-authority-final-activation/HEAD_SCORING_MODEL.json').read_text())
base=json.loads((P/'BASELINE_IDENTITY.json').read_text());base['activeBundle']={'id':'production-authority-bundle-20261020','contentHash':'0057b6ba7d366fcd56b659b39c799e6b5a1c775cf5049fb68b9afe7605053159'};base['scoringExecutable']={'implementation':'m64-clarification-1','version':'1.0.0','manifestContentHash':'dd2e5882d7a88cc6194f9600838fa8da8e22a3be54098e638def31885ea0dfad'};base['currentModelPin']=model['pin'];base['priorAttemptReleaseMatches']=pre['release']==base['previousAttemptRelease'];assert base['priorAttemptReleaseMatches'];save('BASELINE_IDENTITY.json',base)
issues=[{'id':'MARKET_INCOMPLETE_EOD','severity':'MAJOR','status':'OPEN','reason':q['exactBlocker']},{'id':'MARKET_HEAD_AND_SESSION','severity':'MAJOR','status':'OPEN','reason':'No accepted MARKET; active session window expired. No CAS performed after failed qualification.'},{'id':'RUNTIME_DATASET','severity':'MAJOR','status':'OPEN','reason':'0 formal acceptances, snapshots, observations, assessments and derivations; canonical admission is a separate contract.'},{'id':'HUMAN_INPUTS','severity':'MAJOR','status':'UNPROVEN','reason':'No accepted input binds 667 required explicit HUMAN rubric slots and reviewed owner gates/context; no Phase3 approval attempted.'},{'id':'QUALITY_GATES','severity':'MAJOR','status':'OPEN','reason':str(counts['full']['failed'])+' full-suite failures retained; exact historical comparison in REGRESSION_RESULTS.json.'}];save('ISSUES.json',{'critical':[],'major':issues,'minor':[]})
status={'finalStatus':'BLOCKED — PRODUCTION SCORING NOT EXECUTED','stopPhase':1,'universe':{'total':30,'eligible':29,'scored':0,'deferred':1,'blockedEligible':29},'prerequisites':{'productionAuthority':'PASS','marketCapture':'PASS_NOT_QUALIFICATION','marketQualification':q['exactBlocker'],'marketDependency':'BLOCKED','formalScoringDatasetAcceptance':'MISSING_NOT_CREATED','humanCompleteness':'NOT_PROVEN_NO_BOUND_RUNTIME_INPUT'},'scores':0,'ranks':0,'top10':0,'MBB':{'state':'DEFERRED','score':None,'rank':None},'integrity':audit,'testCounts':counts,'head':base['head']};save('FINAL_STATUS.json',status)
lines=['# Production scoring prerequisite closure — blocked','','**BLOCKED — PRODUCTION SCORING NOT EXECUTED**','','Starting and ending HEAD: `'+base['head']+'`. No tracked source/test/authority file changed. The only new tracked candidate is this evidence package. No commit was created by this task.','','## Universe and phase outcome','','30 retained members;29 fundamentally eligible;0 scored;29 blocked eligible;1 deferred MBB. Scores/ranking/Top10/decisions created=0. Phase0 authority replay passed. Phase1 actual source refresh succeeded, but approved EOD qualification failed. Phases2–9 were not executed. Read-only downstream contract/inventory inspection does not constitute admission or human review.','','## Market','','Existing `api/tcbs.mjs --market-only --cached-token-only --history-bars=2` reused a valid private token; no OTP or account API call. Captured93 REST200 responses (61 EOD core) and'+str(refresh['websocketFrames'])+' WSS frames, with all30 symbols and hash replay PASS. Raw source folder: `'+refresh['capturePath']+'`.','','Existing `scripts/build-tcbs-pipeline.mjs` returned `MARKET_BOUNDARY:UNFINISHED_DAILY_BAR`. Board `/tradingDate` is21/10/2026; raw captures occurred around10:06–10:07 Vietnam time. The conservative approved completion bound is15:00 Vietnam time (08:00Z), later than these actual captures. Intraday matches/partial candles cannot prove completed closes. No board date, timestamp or freshness rule was changed; no old snapshot was relabelled current.','','Actual production VALUATION resolution remains `MARKET_BOUNDARY:REFRESH_REQUIRED:UNKNOWN_OR_AMBIGUOUS_SESSION,CURRENT_MARKET_SNAPSHOT_NOT_AVAILABLE`. The active approved policy window ended20/10/2026 at14:59:59.999 Vietnam time. Fresh source acquisition does not silently replace that policy or create MARKET authority. Failed qualification means no accepted MARKET artifact or CAS head binding is legitimate. FUNDAMENTAL_DESCRIPTION still passes.','','## Formal dataset and assessments','','Production still has0 `data_initialization_acceptance`,0 formal snapshot runs/observations/availability assessments/derivations and0 score bindings;30 canonical admission runs remain. Existing Level1/DI documents and approved scoring authority are not runtime dataset admission. `SCORING_DATASET_ACCEPTANCE.json` records the inspected AS_KNOWN snapshot, bridge, independent-review and source/time requirements; no acceptance was invented.','','`HUMAN_ASSESSMENT_STATUS.json` and `HUMAN_ASSESSMENTS.md` list every eligible identity and the23 explicit HUMAN rubric requirements per issuer (667 unbound slots), plus named-analyst and owner-gate inputs. Completion is not proven because no accepted runtime input exists. No historical narrative, LLM output, zero or neutral was promoted to human approval. Phase3 itself was not reached.','','## Authority and integrity','','The active release remains `'+pre['release']['id']+'` / `'+pre['release']['hash']+'`, consistent with the prior attempt. Owner/executable/model/policy/risk/Decision/bundle compatibility and exact hashes replayed PASS;22 sealed JSONs and30 canonical runs,0 accounting regressions.','','MBB = DEFERRED / score=null / rank=null. No normalization, percentile, ranking or Top10 population was constructed.','','Unauthorized fallback: NO. Future-information detection: YES for the attempted future completed-EOD interpretation, caught/rejected by the normalizer; future information admitted/used: NO. Unexpected DB mutation: NO. Investment transactions created: NO. Orders submitted: NO. Entire SQLite bytes, every logical table/row hash, schema and dependency head match the baseline. Existing ledger rows remain12; new rows=0.','','## Validation','','| Gate | Exit/result |','|---|---|']
for result in tests['results']:
 n=result['name'];summary=counts.get(n);detail=(str(summary['passed'])+' passed / '+str(summary['failed'])+' failed') if summary else ('PASS' if result['exitCode']==0 else 'FAIL')
 lines.append('| '+n+' | exit '+str(result['exitCode'])+'; '+detail+' |')
lines+=['','Full-suite historical failure-set comparison: '+('EXACT_MATCH' if oldFailed==failed else 'DIFFERS — inspect REGRESSION_RESULTS.json')+'. '+str(len(failed-oldFailed))+' failed cases are absent from the historical activation failure list. This task made no source/DB changes; do not claim that the older18-failure record fully describes the current baseline. Complete commands/exit codes/logs are retained. No test was hidden, skipped or changed.','','Production scorecard/reproducibility replay: NOT_RUN because no accepted immutable score input or scorecard exists. Passing scoring/golden tests is not a successful production scoring cycle.','','## Issues and safe resume','','Critical integrity violations: none detected. Major open issues: incomplete EOD/current MARKET+session head; missing runtime dataset/bridge acceptance; human completeness unproven; failing quality gates. Minor: none classified.','','Resume only with genuinely completed-session source evidence, fresh qualification and independently authorized matching MARKET/session pins through the existing CAS workflow; then rerun VALUATION and stop if blocked. This is not an instruction to force a prior board date or to treat waiting alone as acceptance. Subsequent runtime dataset/bridge/HUMAN review must satisfy their existing contracts. The accepted market scope is VALUATION only; no new SCORING/RANKING purpose is granted here. No Decision Engine/DCA/allocation/trade milestone is authorized.','','Evidence files carry their actual status. SCORECARDS/RANKING/TOP_10 files were intentionally not created because no such production artifacts exist.']
